 function startMission(){game.phase='trail';story('A trail in the mist','You follow broken branches and faint wheel tracks into the forest. The courier is nowhere in sight. A strip of black cloth snags on a cedar root—and there are fresh footprints leading deeper in.','Eastern forest · cedar path','MISSION ACCEPTED');text('objectiveTitle','Follow the tracks to the courier');text('objectiveText','Someone else has been through here. Stay alert.');text('missionCode','ACTIVE · 001-A');text('roundLabel','TRACKING');text('jutsuName','A choice in the trail');text('jutsuCost','DECISION');text('jutsuDesc','The tracks split at a shallow creek. One path is quick but exposed; the other follows the water and hides your approach.');text('instruction','Choose your approach. Your decision shapes the encounter.');$('sequence').innerHTML='';$('signHelp').textContent='Each path leads to a different tactical advantage.';buttons([{label:'Move through the creek',primary:true,fn:()=>encounter('stealth')},{label:'Take the direct trail',fn:()=>encounter('direct')}])}
 function studyScroll(){text('panelTitle','Field notes');text('roundLabel','REFERENCE');text('jutsuName','The art of hand signs');text('jutsuCost','忍術');text('jutsuDesc','Ninja shape chakra through hand signs. Match the sequence shown to successfully cast a jutsu. You can also use a kunai without spending chakra.');$('sequence').innerHTML=signs.map(s=>`<div class="sign">${s.symbol}</div>`).join('');text('instruction','Press the sign keys in the correct order during combat.');text('signHelp','RAM (Q) · TIGER (W) · SERPENT (E) · DRAGON (R)');buttons([{label:'Understood',primary:true,fn:briefing}])}
 function encounter(style){game.phase='combat';game.enemyHp=style==='stealth'?80:100;game.enemyMax=game.enemyHp;game.hp=style==='stealth'?100:90;game.round=1;game.stealth=style==='stealth';$('combatants').style.display='block';text('enemyName',style==='stealth'?'Forest Bandit':'Masked Rogue');text('enemyStatus',style==='stealth'?'CAUGHT OFF GUARD · C-RANK':'HOSTILE · UNKNOWN RANK');story(style==='stealth'?'Caught in the act':'A masked shinobi','Beyond the creek, you find the courier bound to a tree. A masked rogue steps from the fog, one hand already forming a seal. The scroll is tucked into their vest.','Eastern forest · ravine','HOSTILE CONTACT');text('objectiveTitle','Defeat the masked rogue');text('objectiveText','Recover the sealed scroll and escort the courier to safety.');text('missionRank','C · COMBAT');text('panelTitle','Combat encounter');text('roundLabel','YOUR TURN');text('signHelp','RAM (Q) · TIGER (W) · SERPENT (E) · DRAGON (R)');setBars();chooseJutsu()}
 function chooseJutsu(){game.phase='combat';game.locked=false;game.seq=[];game.input=0;text('roundLabel',`ROUND ${game.round} · YOUR TURN`);text('jutsuName','Choose your technique');text('jutsuCost',`${game.chakra} CHAKRA`);text('jutsuDesc','Select a technique, then enter its hand signs in order. A clean cast strikes before the enemy can react.');text('sequenceLabel','AVAILABLE TECHNIQUES · SELECT TO PREPARE');$('sequence').innerHTML='';text('instruction','');buttons([{label:'Fireball · 18 chakra',primary:true,fn:()=>prepare('fire'),disabled:game.chakra<18},{label:'Shadow Clone · 14 chakra',fn:()=>prepare('clone'),disabled:game.chakra<14},{label:'Kunai strike',fn:()=>prepare('kunai')}]);setBars()}
-function prepare(id){game.current=jutsus[id];game.seq=game.current.seq;game.input=0;text('jutsuName',game.current.name);text('jutsuCost',game.current.cost?`${game.current.cost} CHAKRA`:'NO CHAKRA');text('jutsuDesc',game.current.desc);text('sequenceLabel',game.seq.length?'HAND SIGNS · INPUT IN ORDER':'NO HAND SIGNS REQUIRED');text('instruction',game.seq.length?'Tap or press the matching signs to complete your jutsu.':'Strike now to catch them off guard.');$('sequence').innerHTML=game.seq.length?game.seq.map((key,i)=>{const s=signs.find(x=>x.key===key);return `${i?'<span class="arrow">›</span>':''}<div class="sign" id="sign${i}"><span>${s.symbol}</span><small style="font:8px DM Mono;color:#8f9990">${s.key}</small></div>`}).join(''):'<div class="sign done">✓</div>';buttons(game.seq.length?[{label:'Cancel',fn:chooseJutsu}]:[{label:'Strike',primary:true,fn:()=>cast(0)},{label:'Back',fn:chooseJutsu}]);if(!game.seq.length){cast(0)}}
+function prepare(id){game.current=jutsus[id];game.seq=game.current.seq;game.input=0;text('jutsuName',game.current.name);text('jutsuCost',game.current.cost?`${game.current.cost} CHAKRA`:'NO CHAKRA');text('jutsuDesc',game.current.desc);text('sequenceLabel',game.seq.length?'HAND SIGNS · INPUT IN ORDER':'NO HAND SIGNS REQUIRED');text('instruction',game.seq.length?'Tap or press the matching signs to complete your jutsu.':'Strike now to catch them off guard.');$('sequence').innerHTML=game.seq.length?game.seq.map((key,i)=>{const s=signs.find(x=>x.key===key);return `${i?'<span class="arrow">›</span>':''}<div class="sign ${i===0?'active':''}" id="sign${i}"><span>${s.symbol}</span><small style="font:8px DM Mono;color:#8f9990">${s.key}</small></div>`}).join(''):'<div class="sign done">✓</div>';buttons(game.seq.length?[{label:'Cancel',fn:chooseJutsu}]:[{label:'Strike',primary:true,fn:()=>cast(0)},{label:'Back',fn:chooseJutsu}]);if(!game.seq.length){cast(0)}}
 function signInput(key){if(game.phase!=='combat'||game.locked||!game.current||!game.seq.length)return;const expected=game.seq[game.input];const el=$(`sign${game.input}`);if(key===expected){el.classList.add('done');game.input++;if(game.input>=game.seq.length){game.locked=true;setTimeout(()=>cast(game.current.damage),250)}else{$(`sign${game.input}`).classList.add('active');text('instruction',`Good! Next sign: ${game.seq[game.input]}.`);$('instruction').innerHTML=`Good! Next sign: <em>${game.seq[game.input]}</em>.`}}else{el.classList.add('wrong');setTimeout(()=>el.classList.remove('wrong'),500);game.locked=true;game.chakra=Math.max(0,game.chakra-5);setBars();text('instruction','Wrong sign! Your chakra control falters. Try again.');buttons([{label:'Try again',primary:true,fn:()=>prepare(game.current===jutsus.fire?'fire':game.current===jutsus.clone?'clone':'kunai')},{label:'Use kunai',fn:()=>{game.current=jutsus.kunai;cast(17)}}])}}
 function cast(damage){if(game.phase!=='combat')return;game.locked=true;const j=game.current||jutsus.kunai;if(j.cost)game.chakra=Math.max(0,game.chakra-j.cost);const actual=damage||j.damage;if(game.stealth&&game.round===1)game.enemyHp-=Math.round(actual*1.25);else game.enemyHp-=actual;setBars();text('roundLabel','JUTSU LANDED');text('instruction',`${j.name} hits for ${actual} damage!`);if(game.enemyHp<=0){setTimeout(victory,700);return}buttons([]);setTimeout(enemyTurn,850)}
 function enemyTurn(){if(game.phase!=='combat')return;const damage=game.stealth?12:game.round===1?19:16;game.hp=Math.max(0,game.hp-damage);setBars();text('roundLabel','ENEMY ATTACK');text('instruction',`The rogue counters. You take ${damage} damage.`);if(game.hp<=0){setTimeout(defeat,700);return}if(game.chakra<game.maxChakra){game.chakra=Math.min(game.maxChakra,game.chakra+7);setBars()}game.round++;setTimeout(chooseJutsu,650)}
 function openModal(title,desc,icon,button,action){text('modalTitle',title);text('modalText',desc);text('modalIcon',icon);text('modalBtn',button);$('shade').classList.add('open');$('modalBtn').onclick=()=>{$('shade').classList.remove('open');action()}}
